/* citation hover card */
.ci{position:relative;max-width:440px;padding:18px;overflow:visible!important}
.ci-p{margin:0;font-size:14.5px;line-height:1.75;color:var(--text)}
.ci-n{display:inline-grid;place-items:center;min-width:18px;height:18px;margin:0 2px;padding:0 4px;vertical-align:2px;font-family:var(--mono);font-size:10px;font-weight:700;color:var(--accent);background:var(--accent-bg);border:1px solid var(--accent-icon-line);cursor:pointer;transition:background-color .2s,color .2s}
.ci-n.on,.ci-n:hover,.ci-n:focus-visible{background:var(--accent);color:#fff;outline:none}
.ci-src{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}
.ci-s{display:inline-flex;align-items:center;gap:7px;padding:4px 9px 4px 4px;border:1px solid var(--line);font-size:12px;color:var(--text-dim);transition:border-color .2s,color .2s}
.ci-s b{display:grid;place-items:center;width:18px;height:18px;font-size:10px;color:#fff;background:var(--c,#555)}
.ci-s.on{border-color:var(--accent);color:var(--text)}
.ci-card{position:absolute;z-index:6;width:300px;padding:12px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 18px 44px -18px rgba(0,0,0,.45);opacity:0;visibility:hidden;transform:translateY(6px) scale(.97);transition:opacity .18s ease,transform .32s var(--ease),visibility 0s linear .32s;pointer-events:none}
.ci-card.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .32s var(--ease),visibility 0s}
.ci-ch{display:flex;align-items:center;gap:8px}
.ci-ch b{display:grid;place-items:center;width:22px;height:22px;flex:none;font-size:11px;color:#fff;background:var(--c,#555)}
.ci-ch .t{font-size:13px;font-weight:600;color:var(--text);line-height:1.3}
.ci-ch .d{font-size:11.5px;color:var(--muted)}
.ci-q{margin-top:10px;padding-left:10px;border-left:2px solid var(--accent);font-size:12.5px;line-height:1.55;color:var(--text-dim)}
.ci-q mark{background:var(--accent-bg);color:var(--text)}

/* ---------- citation hover card ---------- */
{
  const ci = $('#ci'), p = $('#ci-p'), src = $('#ci-src'), card = $('#ci-card');
  const S = [
    { t:'Pricing page scroll depth, September', d:'analytics.northwind.co', c:'#5d9bfb', q:'Only <mark>31% of visitors reach the comparison table</mark>, which sits below the plan cards on desktop.' },
    { t:'Onboarding interview notes', d:'Research summary.pdf', c:'#ff5a5f', q:'Five of eight people said they <mark>wanted to compare plans before choosing</mark> and could not find the table.' },
    { t:'Pricing page patterns', d:'designme.agency/journal', c:'#3ecf8e', q:'Teams that <mark>lead with a short comparison</mark> see fewer support questions about what each plan includes.' }
  ];
  p.innerHTML = `Most visitors never reach the comparison table<button class="ci-n" data-i="0">1</button>, and people in interviews asked for it before picking a plan<button class="ci-n" data-i="1">2</button>. Moving a short version above the plans is a common fix<button class="ci-n" data-i="2">3</button> and should cut the questions sales gets about plan limits.`;
  src.innerHTML = S.map((s, i) => `<span class="ci-s" data-i="${i}" style="--c:${s.c}"><b>${i + 1}</b>${s.d}</span>`).join('');
  let hideT = null;
  function show(btn){
    clearTimeout(hideT); const i = +btn.dataset.i, s = S[i];
    $$('.ci-n', p).forEach(b => b.classList.toggle('on', b === btn)); $$('.ci-s', src).forEach(b => b.classList.toggle('on', +b.dataset.i === i));
    card.style.setProperty('--c', s.c);
    card.innerHTML = `<div class="ci-ch"><b>${i + 1}</b><div><div class="t">${s.t}</div><div class="d">${s.d}</div></div></div><div class="ci-q">${s.q}</div>`;
    const cr = ci.getBoundingClientRect(), br = btn.getBoundingClientRect(), w = 300;
    card.style.left = Math.max(8, Math.min(cr.width - w - 8, br.left - cr.left + br.width / 2 - w / 2)) + 'px';
    card.classList.remove('show'); const h = card.offsetHeight;
    const above = br.top - cr.top - h - 10;
    card.style.top = (above > -40 ? above : br.bottom - cr.top + 10) + 'px';
    requestAnimationFrame(() => card.classList.add('show')); Sound.play('stream');
  }
  function hide(){ hideT = setTimeout(() => { card.classList.remove('show'); $$('.ci-n,.ci-s', ci).forEach(b => b.classList.remove('on')); }, 120); }
  $$('.ci-n', p).forEach(b => { b.addEventListener('mouseenter', () => show(b)); b.addEventListener('focus', () => show(b)); b.addEventListener('mouseleave', hide); b.addEventListener('blur', hide); b.addEventListener('click', () => show(b)); });
  $$('.ci-s', src).forEach(s => { s.addEventListener('mouseenter', () => show($(`.ci-n[data-i="${s.dataset.i}"]`, p))); s.addEventListener('mouseleave', hide); });
}
